const {DatabaseSync}=require('node:sqlite'); const db=new DatabaseSync('/bench/home/work/.codegraph/codegraph.db',{readOnly:true});
function refs(name,fp){
  const rows=db.prepare(\`select e.metadata, count(*) c from edges e join nodes t on t.id=e.target where e.kind='calls' and t.name=? and t.file_path=? group by e.metadata\`).all(name,fp);
  const agg={};
  for(const r of rows){ let m={}; try{m=JSON.parse(r.metadata||'{}')}catch{}; const k=(m.refName||'?')+' | '+(m.resolvedBy||'?'); agg[k]=(agg[k]||0)+r.c; }
  console.log('==',name,fp); for(const [k,v] of Object.entries(agg).sort((a,b)=>b[1]-a[1]).slice(0,10)) console.log(' ',v,k);
}
refs('Next','internal/scheduler/parser.go');
refs('CompileToStatement','internal/filter/engine.go');
refs('NewEngine','internal/filter/engine.go');
refs('NewSchema','internal/filter/schema.go');
refs('Stop','internal/scheduler/scheduler.go');
" 2>/dev/null

